console.log("Sample CA:", sampleCA);
const ast = asteroids.find(a => a.pdes === sampleCA.des);
console.log("Asteroid:", ast.pdes, ast.full_name);

const posAst = getPos(ast, sampleCA.jd);
const posEarth = getPos(earth, sampleCA.jd);
const dx = posAst.x - posEarth.x;
const dy = posAst.y - posEarth.y;
const dz = posAst.z - posEarth.z;
const d = Math.hypot(dx, dy, dz);
console.log("Calculated distance to Earth:", d, "au vs CA nominal dist:", sampleCA.dist, "au");
